        protected static void ToStringFields(
            IReflectionGetter item,
            StructuredStringBuilder sb,
            Reflection.Mask<bool>? printMask = null)
        {
            if (printMask?.Data ?? true)
            {
                sb.AppendLine($"Data => {SpanExt.ToHexString(item.Data)}");
            }
            if (printMask?.FormLinks?.Overall ?? true)
            {
                sb.AppendLine("FormLinks =>");
                using (sb.Brace())
                {
                    foreach (var subItem in item.FormLinks)
                    {
                        using (sb.Brace())
                        {
