            if ((equalsMask?.GetShouldTranslate((int)Reflection_FieldIndex.Data) ?? true))
            {
                if (!MemoryExtensions.SequenceEqual(lhs.Data.Span, rhs.Data.Span)) return false;
            }
            if ((equalsMask?.GetShouldTranslate((int)Reflection_FieldIndex.FormLinks) ?? true))
            {
                if (!lhs.FormLinks.SequenceEqualNullable(rhs.FormLinks)) return false;
            }
