        #region DeepCopyIn
        public void DeepCopyIn(
            IReflection item,
            IReflectionGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            if ((copyMask?.GetShouldTranslate((int)Reflection_FieldIndex.Data) ?? true))
            {
                item.Data = rhs.Data.ToArray();
            }
            if ((copyMask?.GetShouldTranslate((int)Reflection_FieldIndex.FormLinks) ?? true))
            {
                errorMask?.PushIndex((int)Reflection_FieldIndex.FormLinks);
                try
                {
                    item.FormLinks.SetTo(
                        rhs.FormLinks
                            .Select(b => (IFormLinkGetter<IStarfieldMajorRecordGetter>)new FormLink<IStarfieldMajorRecordGetter>(b.FormKey)));
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
                }
            }
            DeepCopyInCustom(
                item: item,
                rhs: rhs,
                errorMask: errorMask,
                copyMask: copyMask,
                deepCopy: deepCopy);
        }
        
        partial void DeepCopyInCustom(
            IReflection item,
            IReflectionGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
